225	/**
226	 * Persist a single alert config to the database (upsert).
227	 */
228	async function persistConfigToDb(alertType: AlertType, config: AlertConfig, updatedBy?: string): Promise<void> {
229	  try {
230	    const db = await getDb();
231	    // Upsert: try INSERT ... ON DUPLICATE KEY UPDATE (MySQL/TiDB compatible)
232	    // If the method is unavailable, fall back to separate SELECT + INSERT/UPDATE
233	    const values = {
234	      alertType,
235	      enabled: config.enabled,
236	      threshold: config.threshold,
237	      cooldownMs: config.cooldownMs,
238	      severity: config.severity,
239	      description: config.description,
240	      updatedBy: updatedBy ?? null,
241	    };
242	    const setFields = {
243	      enabled: config.enabled,
244	      threshold: config.threshold,
245	      cooldownMs: config.cooldownMs,
246	      severity: config.severity,
247	      description: config.description,
248	      updatedBy: updatedBy ?? null,
249	    };
250	    try {
251	      // Primary: MySQL/TiDB upsert via Drizzle ORM (all values are parameterized, no raw SQL)
252	      await db.insert(geometryAlertConfigs).values(values).onConflictDoUpdate({ target: geometryAlertConfigs.alertType, set: setFields });
253	    } catch (upsertErr) {
254	      // Fallback for non-MySQL dialects: Drizzle ORM update/insert (still parameterized, safe from SQL injection)
255	      log.warn({ alertType }, 'onDuplicateKeyUpdate failed, falling back to parameterized update/insert');
256	      try {
257	        await db.update(geometryAlertConfigs).set(setFields).where(eq(geometryAlertConfigs.alertType, alertType));
258	      } catch (updateErr) {
259	        log.debug({ alertType, error: updateErr instanceof Error ? updateErr.message : String(updateErr) }, 'Update failed, attempting insert');
260	        await db.insert(geometryAlertConfigs).values(values);
261	      }
262	    }
263	  } catch (err) {
264	    log.error({ alertType, error: err instanceof Error ? err.message : String(err) }, 'Failed to persist alert config to DB');
265	  }
266	}
