 */
export function _resetForTesting(): void {
  alertHistory.length = 0;
  alertIdCounter = 0;
  configsLoaded = false;
  for (const key of Object.keys(lastFiredAt)) {
    lastFiredAt[key as AlertType] = 0;
  }
  for (const window of Object.values(rollingWindows)) {
    window.events.length = 0;
  }
  // Reset to defaults without DB persistence
  for (const [key, value] of Object.entries(defaultAlertConfigs)) {
    alertConfigs[key as AlertType] = { ...value };
  }
}

/**
