tool_use_result.originalFile:
/**
 * Geometry Anomaly Alerting — Real-time anomaly detection with DB persistence
 * and multi-channel notifications.
 *
 * Monitors geometry runtime metrics and fires alerts when thresholds are breached:
 * - Fixation risk exceeding configurable threshold (default 0.8)
 * - Drift score exceeding configurable threshold (default 0.9)
 * - Loop detection rate exceeding configurable threshold (default 10%)
 * - Singularity detection events
 * - Phase transition bursts
 * - Invariant violation accumulation
 * - Compute time degradation
 *
 * Each alert type has:
 * - Configurable threshold (persisted to DB)
 * - Cooldown period (prevents alert storms)
 * - Enable/disable toggle
 * - Severity level
 *
 * Alert configs are loaded from DB on startup and cached in memory.
 * Fired alerts are persisted to both geometry_events and geometry_alert_history tables.
 * Notifications are dispatched to all enabled channels (owner, Slack, email).
 */

import { createLogger } from '../_core/logger';
import { notifyOwner } from '../_core/notification';
import { getDb } from '../db';
import { geometryEvents, geometryAlertConfigs, geometryAlertHistory, notificationChannels } from '../../drizzle/schema';
import { eq, desc, and, sql } from 'drizzle-orm';
import { groupAlertIntoIncident } from './alert-analytics';
import type { GeometryPreGenerationResult, GeometryPostGenerationResult } from './geometry-runtime-bridge';

const log = createLogger('geometry-alerting');

// ─── Concurrency Guard (prevents race conditions in evaluateAlerts) ───
// Promise-based async mutex — ensures only one evaluateAlerts runs at a time
let _lockPromise: Promise<void> | null = null;
let _lockResolve: (() => void) | null = null;

async function acquireEvaluationLock(): Promise<boolean> {
  if (_lockPromise) return false; // Already locked, skip
  _lockPromise = new Promise<void>(resolve => { _lockResolve = resolve; });
  return true;
}

function releaseEvaluationLock(): void {
  const resolve = _lockResolve;
  _lockPromise = null;
  _lockResolve = null;
  if (resolve) resolve();
}

// ─── HTTP Timeout Helper ───
const HTTP_TIMEOUT_MS = 10_000; // 10 second timeout for external HTTP calls

function fetchWithTimeout(url: string, options: RequestInit, timeoutMs = HTTP_TIMEOUT_MS): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  return fetch(url, { ...options, signal: controller.signal }).finally(() => clearTimeout(timer));
}

// ─── Alert Types ───────────────────────────────────────────────────

export type AlertType =
  | 'high_fixation_risk'
  | 'high_drift_score'
  | 'high_loop_rate'
  | 'singularity_burst'
  | 'phase_transition_burst'
  | 'invariant_violation_accumulation'
  | 'compute_degradation';

export type AlertSeverity = 'warning' | 'critical';

export interface AlertConfig {
  enabled: boolean;
  threshold: number;
  cooldownMs: number;
  severity: AlertSeverity;
  description: string;
}

export interface AlertHistoryEntry {
  id: string;
  alertType: AlertType;
  severity: AlertSeverity;
  message: string;
  value: number;
  threshold: number;
  sessionId: string | null;
  firedAt: number;
  acknowledged: boolean;
  acknowledgedAt: number | null;
  acknowledgedBy: string | null;
}

// ─── Default Configuration ─────────────────────────────────────────

const DEFAULT_COOLDOWN_MS = 5 * 60 * 1000; // 5 minutes

const defaultAlertConfigs: Record<AlertType, AlertConfig> = {
  high_fixation_risk: {
    enabled: true,
    threshold: 0.8,
    cooldownMs: DEFAULT_COOLDOWN_MS,
    severity: 'critical',
    description: 'Fixation risk exceeds safe threshold — user may be stuck in emotional loop',
  },
  high_drift_score: {
    enabled: true,
    threshold: 0.9,
    cooldownMs: DEFAULT_COOLDOWN_MS,
    severity: 'critical',
    description: 'Drift score exceeds safe threshold — conversation diverging from emotional baseline',
  },
  high_loop_rate: {
    enabled: true,
    threshold: 0.1, // 10% of recent generations
    cooldownMs: 10 * 60 * 1000, // 10 minutes
    severity: 'warning',
    description: 'Loop detection rate exceeds threshold — repetitive patterns detected',
  },
  singularity_burst: {
    enabled: true,
    threshold: 3, // 3 singularities in window
    cooldownMs: 15 * 60 * 1000, // 15 minutes
    severity: 'critical',
    description: 'Multiple singularity events detected — emotional field collapse risk',
  },
  phase_transition_burst: {
    enabled: true,
    threshold: 5, // 5 transitions in window
    cooldownMs: 10 * 60 * 1000,
    severity: 'warning',
    description: 'Rapid phase transitions detected — unstable emotional regime',
  },
  invariant_violation_accumulation: {
    enabled: true,
    threshold: 10, // 10 violations in window
    cooldownMs: 10 * 60 * 1000,
    severity: 'critical',
    description: 'Invariant violations accumulating — conservation laws being broken',
  },
  compute_degradation: {
    enabled: true,
    threshold: 200, // 200ms total compute time
    cooldownMs: DEFAULT_COOLDOWN_MS,
    severity: 'warning',
    description: 'Geometry compute time exceeding acceptable latency',
  },
};

// ─── In-Memory State ───────────────────────────────────────────────

/** Current alert configuration (mutable at runtime, synced to DB) */
const alertConfigs: Record<AlertType, AlertConfig> = JSON.parse(JSON.stringify(defaultAlertConfigs));

/** Whether configs have been loaded from DB */
let configsLoaded = false;

/** Last fire time per alert type (for cooldown enforcement) */
const lastFiredAt: Record<AlertType, number> = {
  high_fixation_risk: 0,
  high_drift_score: 0,
  high_loop_rate: 0,
  singularity_burst: 0,
  phase_transition_burst: 0,
  invariant_violation_accumulation: 0,
  compute_degradation: 0,
};

/** Rolling window counters for rate-based alerts */
interface RollingWindow {
  events: number[];
  windowMs: number;
}

const rollingWindows: Record<string, RollingWindow> = {
  loops: { events: [], windowMs: 10 * 60 * 1000 },
  singularities: { events: [], windowMs: 15 * 60 * 1000 },
  phaseTransitions: { events: [], windowMs: 10 * 60 * 1000 },
  invariantViolations: { events: [], windowMs: 10 * 60 * 1000 },
  totalGenerations: { events: [], windowMs: 10 * 60 * 1000 },
};

/** In-memory alert history (bounded to last 200 entries, also persisted to DB) */
const alertHistory: AlertHistoryEntry[] = [];
const MAX_ALERT_HISTORY = 200;

let alertIdCounter = 0;

// ─── DB Persistence Layer ─────────────────────────────────────────

/**
 * Load alert configurations from the database.
 * Falls back to defaults for any missing alert types.
 * Called once on first access (lazy initialization).
 */
export async function loadConfigsFromDb(): Promise<void> {
  try {
    const db = await getDb();
    if (!db) {
      log.warn('Alert configs not loaded — database not available, using defaults');
      configsLoaded = true; // Mark as loaded to avoid retrying on every call
      return;
    }
    const rows = await db.select().from(geometryAlertConfigs);

    for (const row of rows) {
      const alertType = row.alertType as AlertType;
      if (alertConfigs[alertType]) {
        alertConfigs[alertType] = {
          enabled: row.enabled,
          threshold: row.threshold,
          cooldownMs: row.cooldownMs,
          severity: row.severity as AlertSeverity,
          description: row.description ?? alertConfigs[alertType].description,
        };
      }
    }

    configsLoaded = true;
    log.info({ loadedCount: rows.length }, 'Alert configs loaded from database');
  } catch (err) {
    log.warn({ error: err instanceof Error ? err.message : String(err) }, 'Failed to load alert configs from DB — using defaults');
    configsLoaded = true; // Mark as loaded to avoid retrying on every call
  }
}

/**
 * Persist a single alert config to the database (upsert).
 */
async function persistConfigToDb(alertType: AlertType, config: AlertConfig, updatedBy?: string): Promise<void> {
  try {
    const db = await getDb();
    if (!db) {
      log.warn({ alertType }, 'Alert config not persisted — database not available');
      return;
    }
    // Upsert: try INSERT ... ON DUPLICATE KEY UPDATE (MySQL/TiDB compatible)
    // If the method is unavailable, fall back to separate SELECT + INSERT/UPDATE
    const values = {
      alertType,
      enabled: config.enabled,
      threshold: config.threshold,
      cooldownMs: config.cooldownMs,
      severity: config.severity,
      description: config.description,
      updatedBy: updatedBy ?? null,
    };
    const setFields = {
      enabled: config.enabled,
      threshold: config.threshold,
      cooldownMs: config.cooldownMs,
      severity: config.severity,
      description: config.description,
      updatedBy: updatedBy ?? null,
    };
    try {
      // Primary: MySQL/TiDB upsert via Drizzle ORM (all values are parameterized, no raw SQL)
      await db.insert(geometryAlertConfigs).values(values).onConflictDoUpdate({ target: geometryAlertConfigs.alertType, set: setFields });
    } catch (upsertErr) {
      // Fallback for non-MySQL dialects: Drizzle ORM update/insert (still parameterized, safe from SQL injection)
      log.warn({ alertType }, 'onDuplicateKeyUpdate failed, falling back to parameterized update/insert');
      try {
        await db.update(geometryAlertConfigs).set(setFields).where(eq(geometryAlertConfigs.alertType, alertType));
      } catch (updateErr) {
        log.debug({ alertType, error: updateErr instanceof Error ? updateErr.message : String(updateErr) }, 'Update failed, attempting insert');
        await db.insert(geometryAlertConfigs).values(values);
      }
    }
  } catch (err) {
    log.error({ alertType, error: err instanceof Error ? err.message : String(err) }, 'Failed to persist alert config to DB');
  }
}

/**
 * Persist a fired alert to the geometry_alert_history table.
 */
async function persistAlertToHistory(entry: AlertHistoryEntry): Promise<void> {
  try {
    const db = await getDb();
    if (!db) {
      log.warn({ alertId: entry.id }, 'Alert not persisted to history table — database not available');
      return;
    }
    await db.insert(geometryAlertHistory).values({
      alertId: entry.id,
      alertType: entry.alertType,
      severity: entry.severity,
      message: entry.message,
      value: entry.value,
      threshold: entry.threshold,
      sessionId: entry.sessionId,
      firedAt: entry.firedAt,
      acknowledged: false,
    });
  } catch (err) {
    log.error({ alertId: entry.id, error: err instanceof Error ? err.message : String(err) }, 'Failed to persist alert to history table');
  }
}

/**
 * Ensure configs are loaded before any operation.
 */
async function ensureConfigsLoaded(): Promise<void> {
  if (!configsLoaded) {
    await loadConfigsFromDb();
  }
}

// ─── Multi-Channel Notification Dispatch ──────────────────────────

export interface NotificationChannelConfig {
  id: number;
  name: string;
  channelType: 'owner' | 'slack' | 'email';
  enabled: boolean;
  config: { webhookUrl?: string; emailTo?: string; emailFrom?: string } | null;
  alertTypes: string[] | null;
  minSeverity: 'warning' | 'critical';
}

/**
 * Dispatch an alert to all enabled notification channels.
 * Each channel is dispatched independently — one failure doesn't block others.
 */
async function dispatchToChannels(
  alertType: AlertType,
  severity: AlertSeverity,
  title: string,
  content: string,
): Promise<void> {
  // Always send to owner (built-in channel)
  try {
    await notifyOwner({ title, content });
    log.info({ alertType }, 'Owner notification sent for geometry alert');
  } catch (notifyError) {
    log.error({ alertType, error: notifyError instanceof Error ? notifyError.message : String(notifyError) }, 'Failed to send owner notification');
  }

  // Load additional channels from DB
  try {
    const db = await getDb();
    if (!db) {
      log.warn({ alertType }, 'Additional notification channels skipped — database not available');
      return;
    }
    const channels = await db.select().from(notificationChannels).where(eq(notificationChannels.enabled, true));

    for (const channel of channels) {
      // Check severity filter
      if (channel.minSeverity === 'critical' && severity !== 'critical') continue;

      // Check alert type filter
      const allowedTypes = channel.alertTypes as string[] | null;
      if (allowedTypes && allowedTypes.length > 0 && !allowedTypes.includes(alertType)) continue;

      try {
        if (channel.channelType === 'slack') {
          await sendSlackNotification(channel, title, content, severity);
        } else if (channel.channelType === 'email') {
          await sendEmailNotification(channel, title, content, severity);
        }
        // 'owner' type channels are handled above
      } catch (channelError) {
        log.error({
          channelId: channel.id,
          channelType: channel.channelType,
          error: channelError instanceof Error ? channelError.message : String(channelError),
        }, 'Failed to dispatch to notification channel');
      }
    }
  } catch (dbError) {
    log.error({ error: dbError instanceof Error ? dbError.message : String(dbError) }, 'Failed to load notification channels from DB');
  }
}

/**
 * Send a Slack webhook notification.
 */
async function sendSlackNotification(
  channel: typeof notificationChannels.$inferSelect,
  title: string,
  content: string,
  severity: AlertSeverity,
): Promise<void> {
  const config = channel.config as { webhookUrl?: string } | null;
  if (!config?.webhookUrl) {
    log.warn({ channelId: channel.id }, 'Slack channel missing webhookUrl');
    return;
  }

  const color = severity === 'critical' ? '#dc2626' : '#f59e0b';

  const response = await fetchWithTimeout(config.webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      attachments: [{
        color,
        title,
        text: content,
        footer: 'Gravito Geometry Alerting',
        ts: Math.floor(Date.now() / 1000),
      }],
    }),
  });

  if (!response.ok) {
    throw new Error(`Slack webhook returned ${response.status}: ${await response.text().catch(() => '')}`);
  }

  log.info({ channelId: channel.id, channelName: channel.name }, 'Slack notification sent');
}

/**
 * Send an email notification via Postmark.
 */
async function sendEmailNotification(
  channel: typeof notificationChannels.$inferSelect,
  title: string,
  content: string,
  severity: AlertSeverity,
): Promise<void> {
  const config = channel.config as { emailTo?: string; emailFrom?: string } | null;
  const postmarkToken = process.env.Postmark;

  if (!postmarkToken) {
    log.warn({ channelId: channel.id }, 'Postmark API token not configured — skipping email notification');
    return;
  }

  if (!config?.emailTo) {
    log.warn({ channelId: channel.id }, 'Email channel missing emailTo');
    return;
  }

  const fromEmail = config.emailFrom ?? 'alerts@gravito.ai';
  const severityBadge = severity === 'critical' ? '[CRITICAL]' : '[WARNING]';

  const response = await fetchWithTimeout('https://api.postmarkapp.com/email', {
    method: 'POST',
    headers: {
      'Accept': 'application/json',
      'Content-Type': 'application/json',
      'X-Postmark-Server-Token': postmarkToken,
    },
    body: JSON.stringify({
      From: fromEmail,
      To: config.emailTo,
      Subject: `${severityBadge} ${title}`,
      TextBody: content,
      HtmlBody: `<div style="font-family: sans-serif; max-width: 600px;">
        <h2 style="color: ${severity === 'critical' ? '#dc2626' : '#f59e0b'}">${severityBadge} ${title}</h2>
        <pre style="background: #f3f4f6; padding: 16px; border-radius: 8px; white-space: pre-wrap;">${content}</pre>
        <p style="color: #6b7280; font-size: 12px; margin-top: 24px;">Gravito Geometry Alerting System</p>
      </div>`,
      MessageStream: 'outbound',
    }),
  });

  if (!response.ok) {
    throw new Error(`Postmark returned ${response.status}: ${await response.text().catch(() => '')}`);
  }

  log.info({ channelId: channel.id, channelName: channel.name, emailTo: config.emailTo }, 'Email notification sent');
}

// ─── Rolling Window Helpers ────────────────────────────────────────

function pruneWindow(window: RollingWindow): void {
  const cutoff = Date.now() - window.windowMs;
  let validStart = 0;
  while (validStart < window.events.length && window.events[validStart] < cutoff) {
    validStart++;
  }
  if (validStart > 0) {
    window.events.splice(0, validStart);
  }
}

const MAX_WINDOW_EVENTS = 1000; // Hard cap to prevent unbounded memory growth
const CIRCUIT_BREAKER_THRESHOLD = 800; // Warn when approaching limit
let circuitBreakerTripped = false;

function recordWindowEvent(windowName: string): void {
  const window = rollingWindows[windowName];
  if (!window) return;

  // Circuit breaker: if memory pressure is high, only prune, don't add
  if (circuitBreakerTripped) {
    pruneWindow(window);
    if (window.events.length < CIRCUIT_BREAKER_THRESHOLD * 0.5) {
      circuitBreakerTripped = false;
      log.info({ windowName }, 'Circuit breaker reset — memory pressure relieved');
    }
    return;
  }

  window.events.push(Date.now());
  pruneWindow(window);

  // Hard cap: if pruning didn't reduce enough, force truncate oldest
  if (window.events.length > MAX_WINDOW_EVENTS) {
    window.events.splice(0, window.events.length - MAX_WINDOW_EVENTS);
  }

  // Check total memory pressure across all windows
  const totalEvents = Object.values(rollingWindows).reduce((sum, w) => sum + w.events.length, 0);
  if (totalEvents > CIRCUIT_BREAKER_THRESHOLD * Object.keys(rollingWindows).length) {
    circuitBreakerTripped = true;
    log.warn({ totalEvents, windowCount: Object.keys(rollingWindows).length }, 'Circuit breaker tripped — high memory pressure in rolling windows');
  }
}

function getWindowCount(windowName: string): number {
  const window = rollingWindows[windowName];
  if (!window) return 0;
  pruneWindow(window);
  return window.events.length;
}

// ─── Alert Firing ──────────────────────────────────────────────────

function isCooldownActive(alertType: AlertType): boolean {
  const config = alertConfigs[alertType];
  const lastFired = lastFiredAt[alertType];
  return Date.now() - lastFired < config.cooldownMs;
}

/**
 * Fire an alert: persist to DB (events + history), add to in-memory history,
 * and dispatch to all notification channels.
 * All operations are non-blocking and error-isolated.
 */
async function fireAlert(
  alertType: AlertType,
  value: number,
  sessionId: string | null,
  contextMessage: string,
): Promise<boolean> {
  const config = alertConfigs[alertType];

  // Check enabled
  if (!config.enabled) return false;

  // Check cooldown
  if (isCooldownActive(alertType)) {
    log.debug({ alertType, cooldownMs: config.cooldownMs }, 'Alert suppressed by cooldown');
    return false;
  }

  // Update last fired time
  lastFiredAt[alertType] = Date.now();

  // Build alert entry
  alertIdCounter++;
  const entry: AlertHistoryEntry = {
    id: `alert_${Date.now()}_${alertIdCounter}`,
    alertType,
    severity: config.severity,
    message: contextMessage,
    value,
    threshold: config.threshold,
    sessionId,
    firedAt: Date.now(),
    acknowledged: false,
    acknowledgedAt: null,
    acknowledgedBy: null,
  };

  // Add to in-memory history (bounded)
  alertHistory.unshift(entry);
  if (alertHistory.length > MAX_ALERT_HISTORY) {
    alertHistory.length = MAX_ALERT_HISTORY;
  }

  log.warn({ alertType, severity: config.severity, value, threshold: config.threshold, sessionId }, contextMessage);

  // Persist to geometry_events table (non-blocking)
  try {
    const db = await getDb();
    if (!db) {
      log.warn({ alertType }, 'Alert not persisted to events table — database not available');
    } else {
      await db.insert(geometryEvents).values({
        sessionId: sessionId ?? 'system',
        eventType: mapAlertTypeToEventType(alertType),
        severity: config.severity,
        message: `[ALERT] ${contextMessage}`,
        metadata: {
          alertType,
          value,
          threshold: config.threshold,
          cooldownMs: config.cooldownMs,
          alertId: entry.id,
        },
        generationIndex: null,
        fixationRisk: alertType === 'high_fixation_risk' ? value : null,
        driftScore: alertType === 'high_drift_score' ? value : null,
      });
    }
  } catch (dbError) {
    log.error({ alertType, error: dbError instanceof Error ? dbError.message : String(dbError) }, 'Failed to persist alert to events table');
  }

  // Persist to durable alert history table (non-blocking)
  persistAlertToHistory(entry).catch((err) => { log.error('[Alerting] Alert history persist failed', err); });

  // Group into incident (non-blocking deduplication)
  groupAlertIntoIncident({
    alertId: entry.id,
    alertType,
    severity: config.severity,
    sessionId,
    value,
    threshold: config.threshold,
    firedAt: entry.firedAt,
  }).catch((err) => {
    log.error({ alertType, error: err instanceof Error ? err.message : String(err) }, 'Failed to group alert into incident');
  });

  // Dispatch to all notification channels (non-blocking)
  const severityEmoji = config.severity === 'critical' ? '🚨' : '⚠️';
  const title = `${severityEmoji} Geometry Alert: ${formatAlertTitle(alertType)}`;
  const content = [
    `**Alert Type:** ${alertType}`,
    `**Severity:** ${config.severity.toUpperCase()}`,
    `**Value:** ${typeof value === 'number' ? value.toFixed(4) : value}`,
    `**Threshold:** ${config.threshold}`,
    `**Session:** ${sessionId ?? 'N/A'}`,
    `**Details:** ${contextMessage}`,
    `**Time:** ${new Date().toISOString()}`,
    '',
    `_${config.description}_`,
  ].join('\n');

  dispatchToChannels(alertType, config.severity, title, content).catch((err) => { log.error('[Alerting] Alert dispatch failed', err); });

  // Broadcast to SSE clients (non-blocking)
  try {
    const { broadcastAlertEvent } = require('./escalation-engine');
    broadcastAlertEvent('alert', {
      id: entry.id,
      alertType,
      severity: config.severity,
      message: contextMessage,
      value,
      threshold: config.threshold,
      sessionId,
      firedAt: entry.firedAt,
    });
    // Also broadcast updated count
    import('./escalation-engine').then(mod => {
      const { getSSEClientCount } = mod;
      if (getSSEClientCount() > 0) {
        getUnacknowledgedCount().then(count => {
          mod.broadcastAlertEvent('count', { count });
        }).catch((err) => { log.error('[Alerting] SSE unacknowledged count broadcast failed', err); });
      }
    }).catch((err) => { log.error('[Alerting] SSE escalation-engine import failed', err); });
  } catch (e) {
    log.debug('[Alerting] SSE broadcast not available', e);
  }

  return true;
}

// ─── Alert Type Mapping ────────────────────────────────────────────

type GeometryEventType = 'fixation_alert' | 'drift_alert' | 'loop_detected' | 'singularity_detected' | 'phase_transition' | 'invariant_violation' | 'compute_timeout';

function mapAlertTypeToEventType(alertType: AlertType): GeometryEventType {
  const mapping: Record<AlertType, GeometryEventType> = {
    high_fixation_risk: 'fixation_alert',
    high_drift_score: 'drift_alert',
    high_loop_rate: 'loop_detected',
    singularity_burst: 'singularity_detected',
    phase_transition_burst: 'phase_transition',
    invariant_violation_accumulation: 'invariant_violation',
    compute_degradation: 'compute_timeout',
  };
  return mapping[alertType];
}

function formatAlertTitle(alertType: AlertType): string {
  const titles: Record<AlertType, string> = {
    high_fixation_risk: 'High Fixation Risk',
    high_drift_score: 'High Drift Score',
    high_loop_rate: 'High Loop Detection Rate',
    singularity_burst: 'Singularity Burst',
    phase_transition_burst: 'Phase Transition Burst',
    invariant_violation_accumulation: 'Invariant Violation Accumulation',
    compute_degradation: 'Compute Time Degradation',
  };
  return titles[alertType];
}

// ─── Main Evaluation Function ──────────────────────────────────────

export interface AlertEvaluationParams {
  sessionId: string;
  preResult: GeometryPreGenerationResult;
  postResult: GeometryPostGenerationResult | null;
  neuroAdvanced?: {
    singularityDetected?: boolean;
    phaseTransitionDetected?: boolean;
    invariantViolations?: number;
  };
}

/**
 * Evaluate geometry results against alert thresholds.
 * Called from the governed generation pipeline after persistence.
 *
 * Non-blocking: all alert operations are fire-and-forget with error isolation.
 * Returns the number of alerts fired (for testing/metrics).
 */
export async function evaluateAlerts(params: AlertEvaluationParams): Promise<number> {
  // Async mutex: prevent concurrent evaluations from racing on rolling windows
  const acquired = await acquireEvaluationLock();
  if (!acquired) {
    log.debug('evaluateAlerts skipped — another evaluation is in progress');
    return 0;
  }
  try {
    return await _evaluateAlertsInner(params);
  } finally {
    releaseEvaluationLock();
  }
}

async function _evaluateAlertsInner(params: AlertEvaluationParams): Promise<number> {
  await ensureConfigsLoaded();

  const { sessionId, preResult, postResult, neuroAdvanced } = params;
  let alertsFired = 0;

  try {
    // Track generation in rolling window
    recordWindowEvent('totalGenerations');

    // 1. High fixation risk
    if (preResult.fixationRisk > alertConfigs.high_fixation_risk.threshold) {
      const fired = await fireAlert(
        'high_fixation_risk',
        preResult.fixationRisk,
        sessionId,
        `Fixation risk ${(preResult.fixationRisk * 100).toFixed(1)}% exceeds threshold ${(alertConfigs.high_fixation_risk.threshold * 100).toFixed(1)}% — stability class: ${preResult.stabilityClass}`,
      );
      if (fired) alertsFired++;
    }

    // 2. High drift score
    if (preResult.driftScore > alertConfigs.high_drift_score.threshold) {
      const fired = await fireAlert(
        'high_drift_score',
        preResult.driftScore,
        sessionId,
        `Drift score ${(preResult.driftScore * 100).toFixed(1)}% exceeds threshold ${(alertConfigs.high_drift_score.threshold * 100).toFixed(1)}%`,
      );
      if (fired) alertsFired++;
    }

    // 3. Loop detection rate
    if (postResult?.loopDetected) {
      recordWindowEvent('loops');
    }
    const totalGens = getWindowCount('totalGenerations');
    const loopCount = getWindowCount('loops');
    const loopRate = totalGens > 0 ? loopCount / totalGens : 0;
    if (loopRate > alertConfigs.high_loop_rate.threshold && totalGens >= 10) {
      const fired = await fireAlert(
        'high_loop_rate',
        loopRate,
        sessionId,
        `Loop detection rate ${(loopRate * 100).toFixed(1)}% (${loopCount}/${totalGens} in window) exceeds threshold ${(alertConfigs.high_loop_rate.threshold * 100).toFixed(1)}%`,
      );
      if (fired) alertsFired++;
    }

    // 4. Singularity burst
    if (neuroAdvanced?.singularityDetected) {
      recordWindowEvent('singularities');
      const singCount = getWindowCount('singularities');
      if (singCount >= alertConfigs.singularity_burst.threshold) {
        const fired = await fireAlert(
          'singularity_burst',
          singCount,
          sessionId,
          `${singCount} singularity events in rolling window (threshold: ${alertConfigs.singularity_burst.threshold})`,
        );
        if (fired) alertsFired++;
      }
    }

    // 5. Phase transition burst
    if (neuroAdvanced?.phaseTransitionDetected) {
      recordWindowEvent('phaseTransitions');
      const ptCount = getWindowCount('phaseTransitions');
      if (ptCount >= alertConfigs.phase_transition_burst.threshold) {
        const fired = await fireAlert(
          'phase_transition_burst',
          ptCount,
          sessionId,
          `${ptCount} phase transitions in rolling window (threshold: ${alertConfigs.phase_transition_burst.threshold})`,
        );
        if (fired) alertsFired++;
      }
    }

    // 6. Invariant violation accumulation
    if (neuroAdvanced?.invariantViolations && neuroAdvanced.invariantViolations > 0) {
      for (let i = 0; i < neuroAdvanced.invariantViolations; i++) {
        recordWindowEvent('invariantViolations');
      }
      const ivCount = getWindowCount('invariantViolations');
      if (ivCount >= alertConfigs.invariant_violation_accumulation.threshold) {
        const fired = await fireAlert(
          'invariant_violation_accumulation',
          ivCount,
          sessionId,
          `${ivCount} invariant violations in rolling window (threshold: ${alertConfigs.invariant_violation_accumulation.threshold})`,
        );
        if (fired) alertsFired++;
      }
    }

    // 7. Compute degradation
    const totalComputeMs = preResult.computeTimeMs + (postResult?.computeTimeMs ?? 0);
    if (totalComputeMs > alertConfigs.compute_degradation.threshold) {
      const fired = await fireAlert(
        'compute_degradation',
        totalComputeMs,
        sessionId,
        `Total compute time ${totalComputeMs.toFixed(1)}ms exceeds threshold ${alertConfigs.compute_degradation.threshold}ms`,
      );
      if (fired) alertsFired++;
    }

    return alertsFired;
  } catch (error) {
    log.error({ error: error instanceof Error ? error.message : String(error) }, 'Alert evaluation failed (non-blocking)');
    return alertsFired;
  }
}

// ─── Configuration API ─────────────────────────────────────────────

/**
 * Get the current alert configuration for all alert types.
 */
export async function getAlertConfigs(): Promise<Record<AlertType, AlertConfig>> {
  await ensureConfigsLoaded();
  return JSON.parse(JSON.stringify(alertConfigs));
}

/**
 * Get configuration for a specific alert type.
 */
export async function getAlertConfig(alertType: AlertType): Promise<AlertConfig> {
  await ensureConfigsLoaded();
  const config = alertConfigs[alertType];
  if (!config) {
    throw new Error(`Unknown alert type: ${alertType}`);
  }
  return { ...config };
}

/**
 * Update the threshold for a specific alert type.
 * Persists to database.
 */
export async function setAlertThreshold(alertType: AlertType, threshold: number, updatedBy?: string): Promise<void> {
  await ensureConfigsLoaded();
  if (!alertConfigs[alertType]) {
    throw new Error(`Unknown alert type: ${alertType}`);
  }
  if (typeof threshold !== 'number' || !isFinite(threshold) || threshold < 0) {
    throw new Error(`Invalid threshold: must be a non-negative finite number, got ${threshold}`);
  }
  alertConfigs[alertType].threshold = threshold;
  await persistConfigToDb(alertType, alertConfigs[alertType], updatedBy);
  log.info({ alertType, threshold }, 'Alert threshold updated and persisted');
}

/**
 * Enable or disable a specific alert type.
 * Persists to database.
 */
export async function setAlertEnabled(alertType: AlertType, enabled: boolean, updatedBy?: string): Promise<void> {
  await ensureConfigsLoaded();
  if (!alertConfigs[alertType]) {
    throw new Error(`Unknown alert type: ${alertType}`);
  }
  alertConfigs[alertType].enabled = enabled;
  await persistConfigToDb(alertType, alertConfigs[alertType], updatedBy);
  log.info({ alertType, enabled }, 'Alert enabled state updated and persisted');
}

/**
 * Update the cooldown period for a specific alert type.
 * Minimum cooldown is 30 seconds. Persists to database.
 */
export async function setAlertCooldown(alertType: AlertType, cooldownMs: number, updatedBy?: string): Promise<void> {
  await ensureConfigsLoaded();
  if (!alertConfigs[alertType]) {
    throw new Error(`Unknown alert type: ${alertType}`);
  }
  const MIN_COOLDOWN_MS = 30_000;
  if (typeof cooldownMs !== 'number' || !isFinite(cooldownMs) || cooldownMs < MIN_COOLDOWN_MS) {
    throw new Error(`Invalid cooldown: must be >= ${MIN_COOLDOWN_MS}ms, got ${cooldownMs}`);
  }
  alertConfigs[alertType].cooldownMs = cooldownMs;
  await persistConfigToDb(alertType, alertConfigs[alertType], updatedBy);
  log.info({ alertType, cooldownMs }, 'Alert cooldown updated and persisted');
}

/**
 * Update the severity for a specific alert type.
 * Persists to database.
 */
export async function setAlertSeverity(alertType: AlertType, severity: AlertSeverity, updatedBy?: string): Promise<void> {
  await ensureConfigsLoaded();
  if (!alertConfigs[alertType]) {
    throw new Error(`Unknown alert type: ${alertType}`);
  }
  if (severity !== 'warning' && severity !== 'critical') {
    throw new Error(`Invalid severity: must be 'warning' or 'critical', got '${severity}'`);
  }
  alertConfigs[alertType].severity = severity;
  await persistConfigToDb(alertType, alertConfigs[alertType], updatedBy);
  log.info({ alertType, severity }, 'Alert severity updated and persisted');
}

/**
 * Reset all alert configurations to defaults.
 * Persists all defaults to database.
 */
export async function resetAlertConfigs(updatedBy?: string): Promise<void> {
  for (const [key, value] of Object.entries(defaultAlertConfigs)) {
    alertConfigs[key as AlertType] = { ...value };
    await persistConfigToDb(key as AlertType, value, updatedBy);
  }
  log.info('Alert configurations reset to defaults and persisted');
}

// ─── Alert History API ─────────────────────────────────────────────

/**
 * Get alert history from database with optional filtering.
 * Falls back to in-memory history if DB is unavailable.
 */
export async function getAlertHistoryFromDb(options?: {
  alertType?: AlertType;
  severity?: AlertSeverity;
  acknowledged?: boolean;
  limit?: number;
}): Promise<AlertHistoryEntry[]> {
  try {
    const db = await getDb();
    if (!db) {
      log.warn('Alert history unavailable from DB — falling back to in-memory');
      return getAlertHistory(options);
    }
    const conditions = [];

    if (options?.alertType) {
      conditions.push(eq(geometryAlertHistory.alertType, options.alertType));
    }
    if (options?.severity) {
      conditions.push(eq(geometryAlertHistory.severity, options.severity));
    }
    if (options?.acknowledged !== undefined) {
      conditions.push(eq(geometryAlertHistory.acknowledged, options.acknowledged));
    }

    const limit = options?.limit ?? 50;
    const whereClause = conditions.length > 0 ? and(...conditions) : undefined;

    const rows = await db.select()
      .from(geometryAlertHistory)
      .where(whereClause)
      .orderBy(desc(geometryAlertHistory.firedAt))
      .limit(limit);

    return rows.map(row => ({
      id: row.alertId,
      alertType: row.alertType as AlertType,
      severity: row.severity as AlertSeverity,
      message: row.message ?? '',
      value: row.value ?? 0,
      threshold: row.threshold ?? 0,
      sessionId: row.sessionId,
      firedAt: row.firedAt,
      acknowledged: row.acknowledged,
      acknowledgedAt: row.acknowledgedAt ?? null,
      acknowledgedBy: row.acknowledgedBy ?? null,
    }));
  } catch (err) {
    log.warn({ error: err instanceof Error ? err.message : String(err) }, 'Failed to load alert history from DB — falling back to in-memory');
    return getAlertHistory(options);
  }
}

/**
 * Get alert history from in-memory cache (fast path).
 */
export function getAlertHistory(options?: {
  alertType?: AlertType;
  severity?: AlertSeverity;
  acknowledged?: boolean;
  limit?: number;
}): AlertHistoryEntry[] {
  let filtered = [...alertHistory];

  if (options?.alertType) {
    filtered = filtered.filter(a => a.alertType === options.alertType);
  }
  if (options?.severity) {
    filtered = filtered.filter(a => a.severity === options.severity);
  }
  if (options?.acknowledged !== undefined) {
    filtered = filtered.filter(a => a.acknowledged === options.acknowledged);
  }

  const limit = options?.limit ?? 50;
  return filtered.slice(0, limit);
}

/**
 * Acknowledge an alert by ID.
 * Updates both in-memory and database.
 */
export async function acknowledgeAlertPersistent(alertId: string, acknowledgedBy: string): Promise<boolean> {
  // Update in-memory
  const entry = alertHistory.find(a => a.id === alertId);
  if (entry) {
    entry.acknowledged = true;
    entry.acknowledgedAt = Date.now();
    entry.acknowledgedBy = acknowledgedBy;
  }

  // Update in database
  try {
    const db = await getDb();
    await db.update(geometryAlertHistory)
      .set({
        acknowledged: true,
        acknowledgedAt: Date.now(),
        acknowledgedBy,
      })
      .where(eq(geometryAlertHistory.alertId, alertId));
    log.info({ alertId, acknowledgedBy }, 'Alert acknowledged in DB');

    // Broadcast acknowledge event + updated count to SSE clients
    try {
      const { broadcastAlertEvent, getSSEClientCount } = require('./escalation-engine');
      broadcastAlertEvent('acknowledge', { alertId, acknowledgedBy, acknowledgedAt: Date.now() });
      if (getSSEClientCount() > 0) {
        getUnacknowledgedCount().then((count: number) => {
          broadcastAlertEvent('count', { count });
        }).catch((err) => { log.error('[Alerting] SSE acknowledge count broadcast failed', err); });
      }
    } catch (e) {
      log.debug('[Alerting] SSE broadcast not available for acknowledge', e);
    }

    return true;
  } catch (err) {
    log.error({ alertId, error: err instanceof Error ? err.message : String(err) }, 'Failed to acknowledge alert in DB');
    return !!entry; // Return true if at least in-memory update succeeded
  }
}

/**
 * Legacy acknowledge (in-memory only) — kept for backward compatibility.
 */
export function acknowledgeAlert(alertId: string, acknowledgedBy: string): boolean {
  const entry = alertHistory.find(a => a.id === alertId);
  if (!entry) return false;
  if (entry.acknowledged) return true;

  entry.acknowledged = true;
  entry.acknowledgedAt = Date.now();
  entry.acknowledgedBy = acknowledgedBy;
  log.info({ alertId, acknowledgedBy }, 'Alert acknowledged');
  return true;
}

/**
 * Get the count of unacknowledged alerts.
 * Uses DB for accurate count, falls back to in-memory.
 */
export async function getUnacknowledgedCount(): Promise<number> {
  try {
    const db = await getDb();
    const result = await db.select({ count: sql<number>`count(*)` })
      .from(geometryAlertHistory)
      .where(eq(geometryAlertHistory.acknowledged, false));
    return result[0]?.count ?? 0;
  } catch (err) {
    log.warn('[Alerting] Failed to get unacknowledged count from DB, falling back to in-memory', err);
    return alertHistory.filter(a => !a.acknowledged).length;
  }
}

/**
 * Get summary statistics for the alert system.
 */
export function getAlertSummary(): {
  totalAlerts: number;
  unacknowledged: number;
  bySeverity: Record<AlertSeverity, number>;
  byType: Record<AlertType, number>;
  lastAlertAt: number | null;
} {
  const bySeverity: Record<AlertSeverity, number> = { warning: 0, critical: 0 };
  const byType: Record<AlertType, number> = {
    high_fixation_risk: 0,
    high_drift_score: 0,
    high_loop_rate: 0,
    singularity_burst: 0,
    phase_transition_burst: 0,
    invariant_violation_accumulation: 0,
    compute_degradation: 0,
  };

  let unacknowledged = 0;
  let lastAlertAt: number | null = null;

  for (const entry of alertHistory) {
    bySeverity[entry.severity]++;
    byType[entry.alertType]++;
    if (!entry.acknowledged) unacknowledged++;
    if (lastAlertAt === null || entry.firedAt > lastAlertAt) {
      lastAlertAt = entry.firedAt;
    }
  }

  return {
    totalAlerts: alertHistory.length,
    unacknowledged,
    bySeverity,
    byType,
    lastAlertAt,
  };
}

// ─── Notification Channel Management API ──────────────────────────

/**
 * Get all notification channels.
 */
export async function getNotificationChannels(): Promise<NotificationChannelConfig[]> {
  try {
    const db = await getDb();
    const rows = await db.select().from(notificationChannels);
    return rows.map(r => ({
      id: r.id,
      name: r.name,
      channelType: r.channelType as 'owner' | 'slack' | 'email',
      enabled: r.enabled,
      config: r.config as NotificationChannelConfig['config'],
      alertTypes: r.alertTypes as string[] | null,
      minSeverity: r.minSeverity as 'warning' | 'critical',
    }));
  } catch (err) {
    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to load notification channels');
    return [];
  }
}

/**
 * Create a new notification channel.
 */
export async function createNotificationChannel(channel: {
  name: string;
  channelType: 'owner' | 'slack' | 'email';
  enabled?: boolean;
  config?: { webhookUrl?: string; emailTo?: string; emailFrom?: string };
  alertTypes?: string[];
  minSeverity?: 'warning' | 'critical';
}): Promise<number> {
  const db = await getDb();
  const [inserted] = await db.insert(notificationChannels).values({
    name: channel.name,
    channelType: channel.channelType,
    enabled: channel.enabled ?? true,
    config: channel.config ?? null,
    alertTypes: channel.alertTypes ?? null,
    minSeverity: channel.minSeverity ?? 'warning',
  }).returning({ id: notificationChannels.id });
  const insertId = inserted?.id ?? 0;
  log.info({ channelName: channel.name, channelType: channel.channelType }, 'Notification channel created');
  return insertId;
}

/**
 * Update an existing notification channel.
 */
export async function updateNotificationChannel(id: number, updates: {
  name?: string;
  enabled?: boolean;
  config?: { webhookUrl?: string; emailTo?: string; emailFrom?: string };
  alertTypes?: string[];
  minSeverity?: 'warning' | 'critical';
}): Promise<boolean> {
  try {
    const db = await getDb();
    await db.update(notificationChannels)
      .set(updates)
      .where(eq(notificationChannels.id, id));
    log.info({ channelId: id }, 'Notification channel updated');
    return true;
  } catch (err) {
    log.error({ channelId: id, error: err instanceof Error ? err.message : String(err) }, 'Failed to update notification channel');
    return false;
  }
}

/**
 * Delete a notification channel.
 */
export async function deleteNotificationChannel(id: number): Promise<boolean> {
  try {
    const db = await getDb();
    await db.delete(notificationChannels).where(eq(notificationChannels.id, id));
    log.info({ channelId: id }, 'Notification channel deleted');
    return true;
  } catch (err) {
    log.error({ channelId: id, error: err instanceof Error ? err.message : String(err) }, 'Failed to delete notification channel');
    return false;
  }
}

// ─── Exported Constants (for testing) ──────────────────────────────

export const ALERT_TYPES: AlertType[] = [
  'high_fixation_risk',
  'high_drift_score',
  'high_loop_rate',
  'singularity_burst',
  'phase_transition_burst',
  'invariant_violation_accumulation',
  'compute_degradation',
];

export const DEFAULT_CONFIGS = defaultAlertConfigs;

// ─── Test Helpers ──────────────────────────────────────────────────

/**
 * Reset all internal state (for testing only).
 */
export function _resetForTesting(): void {
  alertHistory.length = 0;
  alertIdCounter = 0;
  configsLoaded = false;
  for (const key of Object.keys(lastFiredAt)) {
    lastFiredAt[key as AlertType] = 0;
  }
  for (const window of Object.values(rollingWindows)) {
    window.events.length = 0;
  }
  // Reset to defaults without DB persistence
  for (const [key, value] of Object.entries(defaultAlertConfigs)) {
    alertConfigs[key as AlertType] = { ...value };
  }
}

/**
 * Force mark configs as loaded (for testing without DB).
 */
export function _markConfigsLoadedForTesting(): void {
  configsLoaded = true;
}

